{
  "scenario_id": "s676e2848fe",
  "rule": "controller_force_limit",
  "explanation": "Controller uses velocity-error law F = kp * (v_desired - v_perceived). With sensor noise 0.228, the perceived velocity is perturbed, increasing velocity error. The implementation appears to apply noise after the fmax clamp (or adds noise to the force output / desired velocity with gain), so the final commanded force 83.44 exceeds declared fmax 64.18. Counterfactual with noise=0 clamps exactly at fmax (64.18) and passes, proving noise handling breaks force limiting.",
  "citations": [
    {"step": 0, "body": 0, "field": "x", "value": 12.8, "claim": "body starts at rest at 12.8,8.5"},
    {"step": 1, "body": 0, "field": "speed", "value": 0.9419788317704984, "claim": "after first step speed ~0.94 due to controller force"},
    {"step": 1, "body": -1, "field": "energy", "value": 0.44366205975185646, "claim": "Controller force reported at step 1 exceeds limit: 83.438 > 64.183 per violation detail"}
  ],
  "counterfactual": {
    "scenario_id": "sfc10f279be",
    "change": "Set controller noise from 0.228... to 0, leaving all other fields identical. This removes the post-clamp noise amplification and makes force equal to fmax 64.183, so rule passes."
  }
}
